Available Tools: 
Object_Detector_Tool, Text_Detector_Tool

Tools Metadata(JSON): 
```json
{
  "Object_Detector_Tool": {
    "tool_module_name": "object_detector",
    "tool_class_name": "Object_Detector_Tool",
    "tool_description": "A tool that detects objects in an image using the Grounding DINO model and saves individual object images with empty padding.",
    "tool_version": "1.0.0",
    "input_types": {
      "image": "str - The path to the image file.",
      "labels": "list - A list of object labels to detect.",
      "threshold": "float - The confidence threshold for detection (default: 0.35).",
      "model_size": "str - The size of the model to use ('tiny' or 'base', default: 'tiny').",
      "save_object": "bool - Whether to save the detected objects as images (default: False).",
      "saved_image_path": "str - The path to save the detected object images (default: 'detected_objects')."
    },
    "output_types": "\"tuple - A tuple containing two elements: (1) a dictionary mapping each detected label to a list of detection entries, e.g. {'baseball': [{'box': (x1, y1, x2, y2), 'score': 0.95, 'saved_image_path': 'path/to/saved/image.png'}]}, (2) a dictionary mapping each label to the number of detected objects in the image. e.g. {'baseball': 2, 'basket': 1}\".\n",
    "demo_commands": {
      "command": "detected_objects, object_number = Object_Detector_Tool.execute(image=\"path/to/image.png\", labels=[\"baseball\", \"basket\"], save_object=True, saved_image_path=\"detected_objects\")",
      "description": "Detects 'baseball' and 'basket' in the image. Returns a tuple: (1) a dict mapping each label to a list of detection results (each with box, score, and optionally saved image path); (2) a dict with the total count for each detected label. If 'save_object' is True, detected objects are cropped and saved to the specified directory.\"\n",
      "output_example": "detected_objects : {\n'baseball': [{'box': (34, 50, 200, 220), 'score': 0.92, 'saved_image_path': 'detected_objects/image_baseball_1.png'}],\n'basket': [{'box': (220, 100, 400, 350), 'score': 0.85, 'saved_image_path': 'detected_objects/image_basket_1.png'}]\n}\nobject_number : {'baseball': 1, 'basket': 2}\n"
    },
    "user_metadata": {
      "potential usage": "The tool can be used for counting and locating interest-objects in images by utilizing the bounding boxes"
    }
  },
  "Text_Detector_Tool": {
    "tool_module_name": "text_detector",
    "tool_class_name": "Text_Detector_Tool",
    "tool_description": "A tool that detects text in an image using EasyOCR.",
    "tool_version": "1.0.0",
    "input_types": {
      "image": "str - The path to the image file.",
      "languages": "list - A list of language codes for the OCR model.",
      "detail": "int - The level of detail in the output. Set to 0 for simpler output, 1 for detailed output."
    },
    "output_types": "\"list - A list of detected text blocks. Each block contains the bounding box coordinates, the recognized text, and the confidence score (float). e.g. [[[[x0, y0], [x1, y1], [x2, y2], [x3, y3]], \"Detected text\", score], ...]. An empty list is returned if text detection fails after retries.\"\n",
    "demo_commands": {
      "command": "result = Text_Detector_Tool.execute(image='path/to/image.png', languages=['en', 'de'])",
      "description": "Detect text in an image using multiple languages (English and German), including coordinates and confidence scores.",
      "output_example": "[[[[100, 150], [200, 150], [200, 200], [100, 200]], 'Detected text', 0.95], ...]"
    },
    "user_metadata": {
      "frequently_used_language": {
        "ch_sim": "Simplified Chinese",
        "de": "German",
        "en": "English",
        "ja": "Japanese"
      },
